check('The sign-in markup: Google link and label, labeled name fields, Club first, live errors, exact captions and in-app text, no other scripts',()=>{const h=loginHtml;assert.match(h,/<a class="gsi" id="google" href="\/auth\/google"><svg [^>]*aria-hidden="true"[^>]*>[\s\S]*?<\/svg>Sign in with Google<\/a>/);assert.ok(h.includes('<p class="hint">Use your UCLA Google account (it ends in @g.ucla.edu). <a href="/privacy">Privacy</a></p>'));assert.ok(h.includes('<p>Open this page in Safari or Chrome to sign in. Google blocks sign-in inside apps.</p>'));for(const [id,ac] of [['first','given-name'],['last','family-name']])assert.match(h,new RegExp(`<input id="${id}" name="${id}" autocomplete="${ac}" [^>]*maxlength="50" required>`));assert.match(h,/<div class="seg" role="group" aria-label="Sign in as"><button type="button" id="clubTab" aria-pressed="true">Club<\/button><button type="button" id="guestTab" aria-pressed="false">Guest<\/button><\/div>/);assert.match(h,/id="googleError" aria-live="polite"/);assert.match(h,/id="nameError" aria-live="polite"/);assert.ok(h.includes('<p class="note" id="guestNote" hidden>Guests can join and host games. Club practice is members only.</p>'));assert.match(h,/<form method="post" action="\/auth\/logout"><input type="hidden" name="next" value="google"><button class="link">Use a different account<\/button><\/form>/);assert.equal(h.match(/<script/g).length,2);assert.match(h,/<script id="loginConfig" type="application\/json">__LOGIN_CONFIG__<\/script>\s*<script src="\/pickleball-login\.js\?v=__ASSET_VERSION__"><\/script>/)});
check('Inside Instagram, Facebook, TikTok, Snapchat, LinkedIn, X, LINE, WeChat and Android WebViews the Google button becomes "open in Safari or Chrome"; iPhone Safari, Chrome (iPhone, Android) and desktop keep it',()=>{for(const ua of [SAFARI.replace('Safari/604.1','Instagram 350.0.0.21.110 (iPhone14,5; iOS 18_0; en_US)'),SAFARI+' [FBAN/FBIOS;FBAV/480.0.0]','Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Mobile Safari/537.36 musical_ly_37.0 BytedanceWebview/d8a21c6','Snapchat/13.10.0.40 (iPhone14,5)',SAFARI+' LinkedInApp/9.30',SAFARI+' Twitter for iPhone/10.60',SAFARI+' Line/14.0.0',SAFARI.replace('Safari/604.1','MicroMessenger/8.0.50(0x1800322d) NetType/WIFI Language/en'),'Mozilla/5.0 (Linux; Android 14; Pixel 8 Build/AP2A.240905.003; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/129.0.6668.70 Mobile Safari/537.36']){const p=loginPage(googleCfg,{ua});assert.equal(p.els.googleBox.hidden,true,ua);assert.equal(p.els.inApp.hidden,false,ua);assert.equal(p.els.link.value,'https://calendar.invalid/')}for(const ua of [SAFARI,SAFARI.replace('Version/18.0','CriOS/129.0.6668.69'),'Mozilla/5.0 (Linux; Android 14; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0.6668.70 Mobile Safari/537.36','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Safari/537.36']){const p=loginPage(googleCfg,{ua});assert.equal(p.els.googleBox.hidden,false,ua);assert.equal(p.els.inApp.hidden,true,ua)}});
await checkAsync('Copy link copies the site link, or selects it when the clipboard is blocked or missing',async()=>{const wrote=[],p=loginPage(googleCfg,{ua:'Instagram',clipboard:{writeText:async t=>{wrote.push(t)}}});await p.els.copy.onclick();assert.deepEqual(wrote,['https://calendar.invalid/']);assert.equal(p.els.copy.textContent,'Link copied');assert.notEqual(p.els.link.selected,true);for(const clipboard of [{writeText:async()=>{throw new Error('NotAllowedError')}},undefined]){const q=loginPage(googleCfg,{ua:'Instagram',clipboard});await q.els.copy.onclick();assert.equal(q.els.link.selected,true);assert.equal(q.doc.activeElement,q.els.link)}});
check("Without Google secrets the page says Sign-in isn't set up yet. and offers no Google link, even inside an app; a ?e= error shows above the button",()=>{for(const ua of [SAFARI,'Instagram']){const p=loginPage({...googleCfg,ready:false,error:'Sign-in timed out. Try again.'},{ua});assert.equal(p.els.googleError.textContent,"Sign-in isn't set up yet.");assert.equal(p.els.googleBox.hidden,true);assert.equal(p.els.inApp.hidden,true)}const p=loginPage({...googleCfg,error:'Sign-in timed out. Try again.'});assert.equal(p.els.googleError.textContent,'Sign-in timed out. Try again.');assert.equal(p.els.googleBox.hidden,false);assert.equal(loginPage(googleCfg).els.googleError.textContent,'')});
check('The name step shows the account email; a returning guest starts on Guest with the saved name',()=>{let p=loginPage(nameCfg);assert.equal(p.els.email.textContent,'alex@g.ucla.edu');assert.deepEqual(p.pressed(),['true','false']);assert.equal(p.els.card.dataset.tab,'club');assert.equal(p.els.clubNote.hidden,false);assert.equal(p.els.guestNote.hidden,true);p=loginPage({...nameCfg,tab:'guest',first:'Jamie',last:'Visitor'});assert.deepEqual(p.pressed(),['false','true']);assert.equal(p.els.card.dataset.tab,'guest');assert.deepEqual([p.els.first.value,p.els.last.value],['Jamie','Visitor']);assert.equal(p.els.clubNote.hidden,true);assert.equal(p.els.guestNote.hidden,false);p.els.clubTab.onclick();assert.deepEqual(p.pressed(),['true','false']);assert.deepEqual([p.els.first.value,p.els.last.value],['Jamie','Visitor']);assert.equal(p.els.nameError.textContent,'');assert.equal(loginPage({...nameCfg,error:'Sign-in timed out. Try again.'}).els.nameError.textContent,'Sign-in timed out. Try again.')});
await checkAsync('A not-found reply shows the error above Sign in with "Not on the club team? Sign in as a guest" right below it; tapping it switches to Guest and keeps the typed name',async()=>{const p=loginPage(nameCfg,{replies:[[404,{error:NOT_FOUND,code:'not-found'}]]});p.els.first.value='Nobody';p.els.last.value='Here';await p.submit();assert.deepEqual(p.sent,[{url:'/auth/name',method:'POST',body:{tab:'club',first:'Nobody',last:'Here'}}]);assert.equal(p.els.nameError.textContent,NOT_FOUND);assert.equal(p.els.clubNote.hidden,false);assert.equal(p.els.fix.hidden,true);assert.deepEqual([p.els.submit.disabled,p.els.submit.textContent],[false,'Sign in']);assert.match(loginHtml,/id="nameError" aria-live="polite"><\/p>\s*<button type="button" class="link" id="fix" hidden>Switch to Club<\/button>\s*<button class="primary" id="submit">Sign in<\/button>\s*<p class="note" id="clubNote">Not on the club team\? <button type="button" class="link" id="toGuest">Sign in as a guest<\/button><\/p>/);p.els.toGuest.onclick();assert.deepEqual(p.pressed(),['false','true']);assert.equal(p.els.card.dataset.tab,'guest');assert.deepEqual([p.els.first.value,p.els.last.value],['Nobody','Here']);assert.equal(p.els.nameError.textContent,'');assert.deepEqual([p.els.clubNote.hidden,p.els.guestNote.hidden],[true,false]);assert.equal(p.doc.activeElement,p.els.guestTab)});
await checkAsync('A guest name on the roster offers Switch to Club, which keeps the name',async()=>{const p=loginPage({...nameCfg,tab:'guest'},{replies:[[409,{error:'That name is on the club roster. Use the Club tab.',code:'roster-name'}]]});p.els.first.value='Alex';p.els.last.value='Example';await p.submit();assert.equal(p.sent[0].body.tab,'guest');assert.equal(p.els.nameError.textContent,'That name is on the club roster. Use the Club tab.');assert.equal(p.els.fix.hidden,false);p.els.fix.onclick();assert.deepEqual(p.pressed(),['true','false']);assert.equal(p.els.fix.hidden,true);assert.equal(p.els.nameError.textContent,'');assert.deepEqual([p.els.first.value,p.els.last.value],['Alex','Example']);assert.equal(p.doc.activeElement,p.els.clubTab)});
await checkAsync('A 200 {ok:true} reply goes to the calendar and leaves Sign in busy',async()=>{const p=loginPage(nameCfg,{replies:[[200,{ok:true}]]});p.els.first.value='Alex';p.els.last.value='Example';await p.submit();assert.deepEqual(p.go,['/']);assert.deepEqual([p.els.submit.disabled,p.els.submit.textContent],[true,'Signing in…']);assert.equal(p.els.nameError.textContent,'');p.window.onpageshow({persisted:false});assert.deepEqual(p.go,['/']);p.window.onpageshow({persisted:true});assert.deepEqual(p.go,['/','reload'])});
await checkAsync('A network failure or a non-JSON reply says so and re-enables Sign in; a second tap while busy sends nothing',async()=>{const p=loginPage(nameCfg,{replies:[new TypeError('Failed to fetch'),[503,new SyntaxError('not JSON')]]});p.els.first.value='A';p.els.last.value='B';const a=p.submit();await p.submit();await a;assert.equal(p.sent.length,1);assert.equal(p.els.nameError.textContent,'Network problem. Check your connection and try again.');assert.deepEqual([p.els.submit.disabled,p.els.submit.textContent],[false,'Sign in']);await p.submit();assert.equal(p.els.nameError.textContent,"Couldn't sign in right now. Try again.");assert.deepEqual(p.go,[])});
await checkAsync('A signin reply reloads the page so the Google step shows; any error reply puts focus back on Sign in',async()=>{let p=loginPage(nameCfg,{replies:[[401,{error:'Sign in with Google first.',code:'signin'}]]});p.els.first.value='A';p.els.last.value='B';await p.submit();assert.deepEqual(p.go,['reload']);p=loginPage(nameCfg,{replies:[[404,{error:NOT_FOUND,code:'not-found'}]]});p.els.first.value='A';p.els.last.value='B';await p.submit();assert.equal(p.doc.activeElement,p.els.submit);p=loginPage(nameCfg,{replies:[new TypeError('x')]});p.els.first.value='A';p.els.last.value='B';await p.submit();assert.equal(p.doc.activeElement,p.els.submit)});
await checkAsync('Club/Guest switches are ignored while Sign in is busy, and work again after the reply',async()=>{let answer;const p=loginPage(nameCfg,{replies:[new Promise(r=>answer=r)]});p.els.first.value='A';p.els.last.value='B';const a=p.submit();for(const b of ['guestTab','toGuest'])p.els[b].onclick();assert.deepEqual(p.pressed(),['true','false']);answer([404,{error:NOT_FOUND,code:'not-found'}]);await a;assert.equal(p.els.nameError.textContent,NOT_FOUND);p.els.guestTab.onclick();assert.deepEqual(p.pressed(),['false','true'])});
await checkAsync('The name step gives up after 30 s with the network message and focus back on Sign in',async()=>{const p=loginPage(nameCfg,{replies:[Object.assign(new Error('signal timed out'),{name:'TimeoutError'})]});p.els.first.value='A';p.els.last.value='B';await p.submit();assert.equal(p.signals[0]?.ms,3e4);assert.equal(p.els.nameError.textContent,'Network problem. Check your connection and try again.');assert.deepEqual([p.els.submit.disabled,p.els.submit.textContent],[false,'Sign in']);assert.equal(p.doc.activeElement,p.els.submit)});
await checkAsync('Members page: a confirm tap within 400 ms of arming is ignored, and a failed reload clears the rows and shows the error',async()=>{let clock=1e12;const els={},posts=[],replies=[{roster:['Mem One'],links:[{sub:'s1',kind:'member',player:'Mem One',email:'one@example.invalid',linkedAt:1,rosterName:'Mem One',onRoster:true}],blocked:[]},new Error('down')],mk=tag=>({tag,children:[],textContent:'',append(...c){this.children.push(...c)},replaceChildren(){this.children=[]}});
 vm.runInNewContext(fs.readFileSync('public/pickleball-setup.js','utf8'),{document:{getElementById:id=>els[id]??=mk(id),createElement:mk},Date:class extends Date{static now(){return clock}},setTimeout:()=>1,clearTimeout(){},fetch:async(url,o={})=>{if(o.method==='POST'){posts.push(JSON.parse(o.body));return {ok:true,json:async()=>({ok:true})}}const r=url==='/api/members'?replies.shift():{script:'',configured:true};if(r instanceof Error)throw r;return {ok:true,json:async()=>r}}});
 await until(()=>els.roster.children.length===1);const unlink=els.roster.children[0].children[1];assert.equal(unlink.textContent,'Unlink');unlink.onclick();clock+=399;unlink.onclick();await tick();assert.deepEqual(posts,[]);assert.equal(unlink.textContent,'Confirm unlink');clock+=2;unlink.onclick();await until(()=>els['members-error'].textContent==='down');assert.deepEqual(posts,[{action:'unlink',sub:'s1'}]);assert.deepEqual([els.roster.children.length,els.guests.children.length,els.blocked.children.length],[0,0,0])});
check('The calendar reloads when the browser restores it from the back/forward cache, and the 401 error reads "Sign in again."',()=>{assert.ok(calendar.includes("window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()})"));assert.ok(calendar.includes('Your session ended. Sign in again.'));assert.ok(!calendar.includes('Signing you in again'))});
check('Reduced motion turns off every animation and transition, including pseudo-elements like the Club/Guest pill',()=>{const css=fs.readFileSync('public/pickleball-calendar.css','utf8'),m=/@media\(prefers-reduced-motion:reduce\)\{([^{]+)\{animation:none!important;transition:none!important\}\}/.exec(css);assert.ok(m,'reduced-motion block');const sel=m[1].split(',').map(s=>s.trim());for(const s of ['*','*::before','*::after','dialog::backdrop'])assert.ok(sel.includes(s),s);assert.match(css,/\.seg::before\{[^}]*transition:transform/)});
